// The scraper can return several rows for one site (one per page it read), and a row with no
// contact on it at all. Collapse to one row per domain and keep the first of each field, so
// the aggregate at the end counts domains rather than pages.
const best = {};
for (const item of $input.all()) {
  const j = item.json;
  const domain = (j.domain || j.url || '').toString().replace(/^https?:\/\//, '').split('/')[0];
  if (!domain) continue;
  if (!best[domain]) best[domain] = { domain, email: null, phone: null, linkedIn: null, pagesRead: 0 };
  const b = best[domain];
  b.pagesRead += 1;
  if (!b.email && Array.isArray(j.emails) && j.emails.length) b.email = j.emails[0];
  if (!b.phone && Array.isArray(j.phones) && j.phones.length) b.phone = j.phones[0];
  if (!b.linkedIn && Array.isArray(j.linkedIns) && j.linkedIns.length) b.linkedIn = j.linkedIns[0];
}
return Object.keys(best).map((d) => ({ json: best[d] }));

// The reason to aggregate rather than append as you go: hit rate is only meaningful across the
// WHOLE list. "412 of 500 domains gave an email" is a number you can act on; a row-by-row
// append tells you nothing about the 88 that did not.
const rows = ($input.first().json.data || []).filter((r) => r && r.domain);
const withEmail = rows.filter((r) => r.email).length;
const withPhone = rows.filter((r) => r.phone).length;
const pct = (n) => (rows.length ? Math.round((n / rows.length) * 100) : 0);
const stamp = new Date().toISOString().slice(0, 10);
return rows.map((r) => ({ json: {
  ...r,
  runDate: stamp,
  listSize: rows.length,
  emailHitRate: pct(withEmail),
  phoneHitRate: pct(withPhone),
} }));
